def check(args, got, expected):
    s = args[0]
    if not got or s.find(got) == -1:
        return False
    if got != got[::-1]:
        return False
    # Any palindrome of the same max length as expected is valid
    # But since expected is generated by a deterministic reference, let's just check length equality with expected or max possible
    # Actually, we can check if len(got) >= len(expected) and got is a valid palindrome present in s.
    return len(got) >= len(expected)

